const workflowHelp = "Start a workflow: a script that fans work out to workers in one box, as a child session. Any session may start one unless the owner's workflow settings say otherwise, and its end reaches the starter as a reply. script is JavaScript that begins with export const meta = {name, profiles, description, size, repo, gpu}, a pure literal; gpu is GiB of GPU memory for the crew's box, as on session start, and a worker started by agent() has none. args is JSON text, and the script reads it parsed as the global args. Globals: agent(prompt, {profile, schema, label, phase, lane, timeout, worktree}), run(command, {cwd, env, timeout, check, label, phase, lane}), parallel(thunks), pipeline(items, ...stages), merge(results, {base}), workflow(path, args), post(to, text, data, {lane}), phase(title), status(text) and log(...). post() reaches the crew's parent alone, so to is parent or its name. phase is a step's stage and lane the subject it is about, such as lane: g.id; the run page draws each lane's path through the phases. status(text) sets the run's one-line status under its name on the run page and in the Runs list; it is not a step. resume names an ended run, whose finished steps with unchanged keys return their stored results; reload changes a running one. Post data stays separate from text, and large post data and final results reach agents as file attachments. The dyna-workflows skill gives encoding and delivery thresholds, every call's return and failure, resume, worktrees and what a worker knows."

const workflowReloadHelp = "Give a running workflow run a new script. The session that started it, a session above that one and the owner reload it. The crew stops the old script and runs the new one in the same box, on the same branches and journal: a call whose step key finished returns its stored result, one whose step is still running waits for that step's worker, and a new key starts. Running steps the new script does not call run on until the run ends. meta must keep the run's name, repo, size and gpu; profiles and description may change. Reload is for a live run; resume, on run, starts a new run from an ended one."

var methodRows = buildMethodRows(methodTable)

func buildMethodRows(rows []MethodEntry) map[contract.Method]MethodEntry {
	result := make(map[contract.Method]MethodEntry, len(rows))
	for _, row := range rows {
		result[row.Method] = row
	}
	return result
}

// Methods returns the one method table: exactly one row per Method constant,
// in method order. Rows without actions are engine-only or not yet served.
// Callers must not modify the table.
func Methods() []MethodEntry { return methodTable }

const historyHelp = "Read the posts of one conversation in time order: any room's feed (omit room for yours), or with dm the owner's DM with that session, in your own room only; another room's DM is refused; every DM and steer of your room's sessions is readable by any session of the room. around (a post id) centres the page on that post and takes its room and conversation; otherwise it shows the newest. Text over 800 characters is cut; pass the post id as post to read it whole. Another room's text comes wrapped in <outside>. Pass older as before or newer as after to page; limit is at most 50."

const transcriptHelp = "Read a session's turns, newest first: each turn's inputs, posts and final text, and one line per tool call. Only sessions of your own room, yours included: session is a name in your room or an ID of one; another room's transcript is refused. turn reads one turn. Text over 800 characters is cut; pass turn with item (an id from cut), and offset for the rest, to read it whole. Pass next as before for older turns; limit is at most 5."
